// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Only test with the admin address (the deployer) as msg.sender
        vm.assume(_owner != address(0) && _owner != address(c));
        vm.prank(address(0xb0b)); // this shouldn't matter anyway
        // The deployer is the admin, so we use the default msg.sender
        address admin = 0x7FA9385bE102ac3EAc297483Dd6233D62b3e1496; // from constructor
        vm.prank(admin);
        bool success = c.setOwner(_owner);
        assertTrue(success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Skip the zero address as it might be a special case
        vm.assume(newOwner != address(0));

        // Store the original owner before the call
        address oldOwner = c.owner();

        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        // The transaction should succeed (onlyAdmin modifier may revert)
        assertTrue(success);

        // The owner should now be the newOwner (not the old one, unless newOwner == oldOwner)
        assertTrue(c.owner() == newOwner);
    }
}
